      &\geq\mathcal{B}_{\mathrm{diff}}(\bm{x}_0),\\
    \mathcal{J}_{\mathrm{diff}}(\bm{x}_0)
      &=\mathbb{E}_{q(\bm{x}_{1:T}\mid\bm{x}_0)}
