\begin{equation}
  \label{eq:pgm-generative-dsm-decomposition}
  \mathbb{E}\lVert\bm{s}_{\bm{\theta}}-\bm{a}\rVert_2^2
  =\mathbb{E}\lVert\bm{s}_{\bm{\theta}}-\bm{s}_t^*\rVert_2^2
   +\mathbb{E}\lVert\bm{a}-\bm{s}_t^*\rVert_2^2.
